contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);
        require(contract_address != address(0x0));
        require(contract_address != address(c));

        uint256 balBefore = address(c).balance;

        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        assert(!ok || (balAfter == balBefore));
    }

    receive() external payable {}
}

